    output_matrix = []
    for row in input_matrix:
        new_row = []
        for val in row:
            if val == 7:
                new_row.extend([7, 1])
            elif val == 3:
                new_row.append(3)
                new_row.append(0)
            elif val == 2:
                new_row.append(2)
                new_row.append(0)
            else:
                new_row.append(0)
        output_matrix.append(new_row)
    return output_matrix

